cat > $J/claim/AuditClaimEdited.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.plugin.variable.Val;

/** Records a stored claim edit: CLAIM_EDITED sheet=<id> by=<user> person=<name> amount=<0.00> date=<yyyy-mm-dd>. */
public class AuditClaimEdited {
    public void audit(@Val ClaimInput input, @Val Claim claim, PersonStore people, Audit audit) {
        audit.record(line("CLAIM_EDITED", input, people.find(claim.getSheetId(), claim.getPersonId()), claim));
    }

    static String line(String event, ClaimInput input, Person person, Claim claim) {
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + claim.getSheetId() + " by=" + input.user() + " person=" + person.getName()
                + " amount=" + shown.amount() + " date=" + shown.date();
    }
}
EOF
cd resources/officefloor/rest/api/sheets/{sheetId}
python3 - <<'EOF'
import re
for f,cls in [("people.POST.yml","net.officefloor.hq.app.person.AuditPersonAdded"),
              ("people/{personId}.PUT.yml","net.officefloor.hq.app.person.AuditPersonEdited"),
              ("people/{personId}/claims.POST.yml","net.officefloor.hq.app.claim.AuditClaimAdded"),
              ("claims/{claimId}.PUT.yml","net.officefloor.hq.app.claim.AuditClaimEdited")]:
    s=open(f).read()
    head,tail=s.split("save:\n",1)
    body,rest=tail.split("respond:\n",1)
    body=body.replace("next: respond","next: audit")
    s=head+"save:\n"+body+"audit:\n  class: "+cls+"\n  govern: [ transaction ]\n  next: respond\nrespond:\n"+rest
    open(f,"w").write(s)
EOF
cat claims/*.PUT.yml

